  "description": "Tính cosin của góc nhị diện tạo bởi mặt phẳng (SBC) và mặt phẳng đáy (ABCD) dọc theo cạnh chung BC của hình chóp S.ABCD có đáy ABCD là hình vuông cạnh a, SA vuông góc với mặt phẳng đáy và SA = a.",
  "memory_declarations": [
    {
      "name": "a",
      "type": "float",
      "initial_value": 1.0,
      "model_assumption": "Giả sử cạnh a = 1 để dễ dàng thiết lập tọa độ."
    },
    {
      "name": "A",
      "type": "point3",
      "at": [0, 0, 0],
      "label": "A",
      "source_fact_id": "đỉnh A"
    },
    {
      "name": "B",
      "type": "point3",
      "at": ["a", 0, 0],
      "label": "B",
      "source_fact_id": "đỉnh B"
    },
    {
      "name": "D",
      "type": "point3",
      "at": [0, "a", 0],
      "label": "D",
      "source_fact_id": "đỉnh D"
    },
    {
      "name": "C",
      "type": "point3",
      "at": ["a", "a", 0],
      "label": "C",
      "source_fact_id": "đỉnh C"
    },
    {
      "name": "S",
      "type": "point3",
      "at": [0, 0, "a"],
      "label": "S",
      "source_fact_id": "đỉnh S"
    },
    {
      "name": "plane_ABCD",
      "type": "plane3",
      "label": "(ABCD)"
    },
    {
      "name": "plane_SBC",
      "type": "plane3",
      "label": "(SBC)"
    },
    {
      "name": "line_BC",
      "type": "line3",
      "label": "BC"
    },
    {
      "name": "line_AB",
      "type": "line3",
      "label": "AB"
    },
    {
      "name": "line_SB",
      "type": "line3",
      "label": "SB"
    },
    {
      "name": "line_SA",
      "type": "line3",
      "label": "SA"
    },
    {
      "name": "angle_cos_val",
      "type": "float",
      "label": "cos(góc nhị diện)"
    }
  ],
  "statements": [
    {
      "kind": "construct_plane",
      "target_var": "plane_ABCD",
      "through": ["A", "B", "D"],
      "label": "Dựng mặt phẳng đáy (ABCD)"
    },
    {
      "kind": "construct_plane",
      "target_var": "plane_SBC",
      "through": ["S", "B", "C"],
      "label": "Dựng mặt phẳng (SBC)"
    },
    {
      "kind": "construct_line",
      "target_var": "line_BC",
      "through_a": "B",
      "through_b": "C",
      "label": "Xác định giao tuyến BC của hai mặt phẳng"
    },
    {
      "kind": "construct_line",
      "target_var": "line_AB",
      "through_a": "A",
      "through_b": "B",
      "label": "Dựng đường thẳng AB trong mặt phẳng đáy (ABCD). Vì ABCD là hình vuông nên AB ⊥ BC."
    },
    {
      "kind": "construct_line",
      "target_var": "line_SA",
      "through_a": "S",
      "through_b": "A",
      "label": "Dựng đường thẳng SA. Theo đề bài, SA ⊥ (ABCD), suy ra SA ⊥ BC."
    },
    {
      "kind": "construct_line",
      "target_var": "line_SB",
      "through_a": "S",
      "through_b": "B",
      "label": "Dựng đường thẳng SB. Vì BC ⊥ AB và BC ⊥ SA (hai đường thẳng cắt nhau tại A trong mặt phẳng (SAB)), suy ra BC ⊥ (SAB). Do đó, BC ⊥ SB."
    },
    {
      "kind": "assign",
      "target_var": "angle_cos_val",
      "expr": {
        "kind": "measure",
        "quantity": "angle_cos",
        "of": "line_AB",
        "wrt": "line_SB"
      },
      "label": "Góc nhị diện giữa (SBC) và (ABCD) là góc giữa hai đường thẳng AB và SB, tức là góc SBA. Tính cosin của góc này."
    }
  ],
  "visual_bindings": {
    "containers": [],
    "pointers": [],
    "value_boxes": [
      {
        "box_id": "box_a",
        "var_ref": "a",
        "label": "Cạnh a"
      },
      {
        "box_id": "box_angle_cos",
        "var_ref": "angle_cos_val",
        "label": "cos(Góc nhị diện)"
      }
    ]
  },
  "pedagogical_intent": "Chương trình minh họa cách xác định góc nhị diện bằng cách tìm hai đường thẳng cùng vuông góc với giao tuyến trong mỗi mặt phẳng, sau đó tính cosin của góc giữa chúng."
}

