      "through_a": { "kind": "var", "name": "Q" },
      "through_b": { "kind": "var", "name": "R" },
      "label": "Giao tuyến QR"
    },
    {
      "kind": "construct_line",
      "target_var": "line_pq",
      "through_a": { "kind": "var", "name": "P" },
      "through_b": { "kind": "var", "name": "Q" },
      "label": "Đường PQ (trong mặt phẳng đáy, vuông góc QR)"
