    {
      "kind": "construct_line",
      "target_var": "line_mq",
      "through_a": { "kind": "var", "name": "M" },
      "through_b": { "kind": "var", "name": "Q" },
      "label": "Đường MQ (trong mặt phẳng MQR, vuông góc QR)"
